// Prepare the LLM Prompt with incoming ticket details
const item = $input.first().json.body || $input.first().json;

const title = item.title || 'Untitled Ticket';
const description = item.description || 'No description provided';
const category = item.category || 'General';
const location = item.location || 'Community Premises';

const prompt = `You are the AI Operations Director for Mana Community Society.
Analyze the following maintenance ticket and classify it accurately.

Ticket Information:
- Title: ${title}
- Description: ${description}
- Reported Category: ${category}
- Location: ${location}

Respond ONLY with a valid JSON object matching this exact format:
{
  "urgency": "CRITICAL" | "HIGH" | "MEDIUM" | "LOW",
  "assignedDepartment": "Plumbing" | "Electrical" | "Elevator" | "Security" | "Civil & Painting" | "Housekeeping" | "Gardening" | "General",
  "suggestedAction": "Short description of immediate corrective action",
  "estimatedResolutionHours": number,
  "safetyHazard": boolean
}`;

return [{
  json: {
    ticketId: item.ticketId || item.id,
    title,
    description,
    prompt
  }
}];

// Parse Gemini AI response and construct triage payload
const geminiResponse = $input.first().json;
let parsedAiAnalysis = {};

try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  parsedAiAnalysis = JSON.parse(rawText);
} catch (err) {
  parsedAiAnalysis = {
    urgency: "MEDIUM",
    assignedDepartment: "General",
    suggestedAction: "Manual inspection required",
    estimatedResolutionHours: 24,
    safetyHazard: false
  };
}

const ticketId = $('Format AI Prompt').first().json.ticketId;

return [{
  json: {
    status: "success",
    ticketId: ticketId,
    triagedAt: new Date().toISOString(),
    analysis: parsedAiAnalysis
  }
}];
